+{
+  "info": {
+    "description": "A curated read-only subset of the Dropbox API v2, shipped with the mcpx dropbox example declaration (#1936). Dropbox publishes its full specification in Stone format; this document covers only the read operations the declaration exposes: listing folders, reading metadata, searching file content and names, and reading the caller's own account. API v2 is RPC over POST \u2014 the verb is POST for reads as well, which is why the declaration sets methods explicitly.",
+    "title": "Dropbox (mcpx example subset)",
+    "version": "1.0.0"
+  },
+  "openapi": "3.0.3",
+  "paths": {
+    "/files/get_metadata": {
+      "post": {
+        "description": "Returns the metadata for the file or folder at path: name, size, timestamps and content hash where the service provides them.",
+        "operationId": "getMetadata",
+        "requestBody": {
+          "content": {
+            "application/json": {
+              "schema": {
+                "properties": {
+                  "path": {
+                    "description": "The path or id of the file or folder.",
+                    "type": "string"
+                  }
+                },
+                "required": [
+                  "path"
+                ],
+                "type": "object"
+              }
+            }
+          },
+          "required": true
+        },
+        "responses": {
+          "200": {
+            "description": "The entry's metadata."
+          }
+        },
+        "summary": "Read one file or folder's metadata",
+        "tags": [
+          "files"
+        ]
+      }
+    },
+    "/files/list_folder": {
+      "post": {
+        "description": "Lists the files and folders directly inside the folder at path (the empty string is the root). Results may be paged; continue with listFolderContinue and the returned cursor.",
+        "operationId": "listFolder",
+        "requestBody": {
+          "content": {
+            "application/json": {
+              "schema": {
+                "properties": {
+                  "limit": {
+                    "description": "Maximum number of entries to return.",
+                    "type": "integer"
+                  },
+                  "path": {
+                    "description": "The folder path, e.g. /Homework/math; empty string for the root.",
+                    "type": "string"
+                  },
+                  "recursive": {
+                    "description": "List everything below the folder as well.",
+                    "type": "boolean"
+                  }
+                },
+                "required": [
+                  "path"
+                ],
+                "type": "object"
+              }
+            }
+          },
+          "required": true
+        },
+        "responses": {
+          "200": {
+            "description": "The folder listing."
+          }
+        },
+        "summary": "List the contents of a folder",
+        "tags": [
+          "files"
+        ]
+      }
+    },
+    "/files/list_folder/continue": {
+      "post": {
+        "description": "Returns the next page of a listing started by listFolder, given its cursor.",
+        "operationId": "listFolderContinue",
+        "requestBody": {
+          "content": {
+            "application/json": {
+              "schema": {
+                "properties": {
+                  "cursor": {
+                    "description": "The cursor returned by the previous listFolder call.",
+                    "type": "string"
+                  }
+                },
+                "required": [
+                  "cursor"
+                ],
+                "type": "object"
+              }
+            }
+          },
+          "required": true
+        },
+        "responses": {
+          "200": {
+            "description": "The next page of the folder listing."
+          }
+        },
+        "summary": "Continue a folder listing",
+        "tags": [
+          "files"
+        ]
+      }
+    },
+    "/files/search_v2": {
+      "post": {
+        "description": "Searches the caller's Dropbox for files whose name or content matches the query string.",
+        "operationId": "searchFiles",
+        "requestBody": {
+          "content": {
+            "application/json": {
+              "schema": {
+                "properties": {
+                  "options": {
+                    "description": "Search options, e.g. max_results and a path restriction.",
+                    "properties": {
+                      "max_results": {
+                        "type": "integer"
+                      },
+                      "path": {
+                        "type": "string"
+                      }
+                    },
+                    "type": "object"
+                  },
+                  "query": {
+                    "description": "The search string.",
+                    "type": "string"
+                  }
+                },
+                "required": [
+                  "query"
+                ],
+                "type": "object"
+              }
+            }
+          },
+          "required": true
+        },
+        "responses": {
+          "200": {
+            "description": "The matching files."
+          }
+        },
+        "summary": "Search files by name and content",
+        "tags": [
+          "files"
+        ]
+      }
+    },
+    "/users/get_current_account": {
+      "post": {
+        "description": "Returns the account the access token belongs to: account id, display name, email and account type. Takes no arguments.",
+        "operationId": "getCurrentAccount",
+        "responses": {
+          "200": {
+            "description": "The caller's account."
+          }
+        },
+        "summary": "Read the caller's own account",
+        "tags": [
+          "users"
+        ]
+      }
+    }
+  },
+  "servers": [
+    {
+      "url": "https://api.dropboxapi.com/2"
+    }
+  ]
+}

