+            "in": "query",
+            "name": "q",
+            "schema": {
+              "type": "string"
+            }
+          },
+          {
+            "description": "Maximum number of files to return.",
+            "in": "query",
+            "name": "pageSize",
+            "schema": {
+              "type": "integer"
+            }
+          },
+          {
+            "description": "Comma-separated fields to include for each file.",
+            "in": "query",
+            "name": "fields",
+            "schema": {
+              "type": "string"
+            }
+          },
+          {
+            "description": "Sort order, e.g. modifiedTime desc.",
+            "in": "query",
+            "name": "orderBy",
+            "schema": {
+              "type": "string"
+            }
+          }
+        ],
+        "responses": {
+          "200": {
+            "description": "The matching files."
+          }
+        },
+        "summary": "List and search files",
+        "tags": [
+          "files"
+        ]
+      }
+    },
+    "/files/{fileId}": {
+      "get": {
+        "description": "Returns the metadata for one file: name, MIME type, size, timestamps, owners and parents. This reads metadata only, not the file's contents.",
+        "operationId": "getFile",
+        "parameters": [
+          {
+            "description": "The id of the file.",
+            "in": "path",
+            "name": "fileId",
+            "required": true,
+            "schema": {
+              "type": "string"
+            }
+          },
+          {
+            "description": "Comma-separated fields to include.",
+            "in": "query",
+            "name": "fields",
+            "schema": {
+              "type": "string"
+            }
+          }
+        ],
+        "responses": {
+          "200": {
+            "description": "The file's metadata."
+          }
+        },
+        "summary": "Read one file's metadata",
+        "tags": [
+          "files"
+        ]
+      }
+    }
+  },
+  "servers": [
+    {
+      "url": "https://www.googleapis.com/drive/v3"
+    }
+  ]
+}

